#pragma once#include "./rsuErr.h"/////////////////////////////////////////////////////////#undef WRT_VAR#define WRT_VAR(Var) WriteFile ( hFile, &Var, sizeof ( Var ), &Lw, NULL ); #undef WRT_DATA#define WRT_DATA(L,Data) WriteFile ( hFile, Data, L, &Lw, NULL );#undef WRT_ARR#define WRT_ARR(Data) WriteFile ( hFile, Data, sizeof(Data), &Lw, NULL );#undef WRT_CLASS#define WRT_CLASS(Class,K,Data) \  {\  DWORD L = lstrlen ( #Class );\  WriteFile ( hFile, &L, 1, &Lw, NULL );\  WriteFile ( hFile, #Class, L, &Lw, NULL );\  L = sizeof(Class);\  WriteFile ( hFile, &L, 4, &Lw, NULL );\  WriteFile ( hFile, &K, 4, &Lw, NULL );\  WriteFile ( hFile, Data, K * L, &Lw, NULL );\  }#undef WRT_STR#define WRT_STR(Str) \  {\  DWORD L = lstrlen ( Str );\  ASS(L<0x10000)\  WriteFile ( hFile, &L, 2, &Lw, NULL );\  WriteFile ( hFile, Str, L, &Lw, NULL );\  }#undef WRT_KEY#define WRT_KEY(Key) { DWORD K = Key; WriteFile ( hFile, &K, sizeof ( K ), &Lw, NULL ); }/////////////////////////////////////////////////////////static BOOL ReadImpl( HANDLE hFile, BYTE* pData, DWORD sr, DWORD &Lr){  BOOL b = ReadFile ( hFile, pData, sr, &Lr, NULL );   ASS( b );  return b;}template<class T>void Read( HANDLE hFile, T *var, DWORD sr, DWORD &Lr ){  ReadImpl( hFile, (BYTE*)var, sr, Lr );}#undef READ_VAR#define READ_VAR(Var) Read( hFile, &Var, sizeof( Var ), Lr ); #undef READ_DATA#define READ_DATA(L,Data) ReadFile ( hFile, Data, L, &Lr, NULL );#undef READ_ARR#define READ_ARR(Data) ReadFile ( hFile, Data, sizeof(Data), &Lr, NULL );#undef READ_CLASStemplate<typename Class, typename tK>bool ReadClassImpl( HANDLE hFile, Class **Data, tK K, LPCSTR pszClass ){  DWORD Lr = 0;  DWORD L = 0;  ReadFile ( hFile, &L, 1, &Lr, NULL );  char ClassName[32];  ReadFile ( hFile, ClassName, L, &Lr, NULL );  ClassName[L] = 0;  int Res = strcmp ( ClassName, pszClass );  ASSR( Res == 0, false )  L = 0;  ReadFile ( hFile, &L, 4, &Lr, NULL );  ASSR(L == sizeof(Class), false);  int Kr = 0;  ReadFile ( hFile, &Kr, 4, &Lr, NULL );  ASSR( Kr == K, false )  if ( *Data == NULL )     *Data = new Class[K];  ReadFile ( hFile, *Data, K * L, &Lr, NULL );  return true;}#define READ_CLASS(Class,K,Data) \  {\  if( !ReadClassImpl( hFile, &Data, K, #Class ) ) return false;\  }#undef READ_STRtemplate<size_t _S>void ReadStrImpl( HANDLE hFile, char (&Str)[_S]){  Str[0] = 0;  DWORD L = 0, Lr = 0;  ReadFile ( hFile, &L, 2, &Lr, NULL );  ASS( L+1 <= sizeof ( Str ));  ReadFile ( hFile, Str, L, &Lr, NULL );  Str[L] = 0;}#define READ_STR(Str) \  ReadStrImpl( hFile, Str );#undef READ_KEYtemplate<typename T>bool READ_KEY_impl( T Key, HANDLE hFile ){  DWORD K = 0;  DWORD Lr = 0;  ReadFile ( hFile, &K, sizeof ( K ), &Lr, NULL );  if ( K != Key )  {    ASS(FALSE)    return false;  }  return true;}#define READ_KEY(Key, retErr ) \  {\  if( !READ_KEY_impl( Key, hFile ) )\    {\    ASS(FALSE)\    return retErr;\    }\  }